+        // affirmait faussement que le retry le sauterait "par idempotence
+        // assumée". Pour les `kind` prouvés sûrs à rejouer (voir
+        // `RETRYABLE_ON_FAILURE_KINDS` ci-dessus), le marqueur est
+        // ENTIÈREMENT retiré : le prochain `cmdImport` ne le verra plus via
+        // `fileExists` (ligne ~2871) et retentera réellement le side-effect.
+        // Pour les autres, le marqueur RESTE (scellement inchangé) mais son
+        // `status` passe de `'applying'` (un mensonge une fois l'échec connu)
+        // à `'failed'` — l'état réel, pas un artefact de l'ordre d'écriture.
+        const retryable = RETRYABLE_ON_FAILURE_KINDS.has(r.kind);
+        if (retryable) {
+          await rm(markerP, { force: true });
+          outcomes.push(
+            `${itemKey} : side-effect en échec (${detail}) — marqueur retiré, un retry REJOUERA cet item (kind "${r.kind}" prouvé sûr à rejouer)`,
+          );
+        } else {
+          await writeMarker(markerP, resultsBranch.sha, itemKey, 'failed');
