  // Nuit no-op légitime : si le manifeste cargo du jour existe et ne
  // contient AUCUN item `export` (que du local_only/deferred), le contrat
  // de la routine cloud est de ne rien pousser — l'absence de results/
  // est alors ATTENDUE, pas un écart. Ouvrir une conversation d'approbation
  // ici serait un faux positif (vécu la première nuit pilote : 1 item
  // local_only, 0 export, et l'import réveillait le hub pour rien).
  const cargoForNoop = await fetchBranchContent(target, cargoRef, scratch);
  const noopManifestRaw = cargoForNoop?.readTextFile('manifest.json');
  const noopParsed = noopManifestRaw ? ExportManifestSchema.safeParse(safeJsonParse(noopManifestRaw)) : undefined;
  if (noopParsed?.success && !noopParsed.data.items.some((i) => i.disposition === 'export')) {
    process.stdout.write(
      [
        'VERDICT: NOOP',
        `Cible : ${target}`,
        `Raison : manifeste ${cargoRef} sans aucun item exporté — aucune branche ${resultsRef} attendue du cloud (nuit no-op légitime).`,
      ].join('\n') + '\n',
    );
    return;
  }
  const gaps = [`branche ${resultsRef} absente sur ${target} — le round cloud ne semble pas avoir tourné cette nuit`];
  let gapDetail = '';
  if (!opts.dryRun) {
    const r = await openGapConversation(date, gaps, 'approval');
    gapDetail = r.detail;
  }
  process.stdout.write(
    [
      'VERDICT: IMPORT_GAP',
      `Cible : ${target}`,
      ...gaps.map((g) => `- ${g}`),
      opts.dryRun ? '--dry-run : conversation d’écart NON ouverte.' : gapDetail,
    ].join('\n') + '\n',
  );
  return;
}

const resolved = resolveBranchResults(resultsBranch, resultsRef);
if (!resolved) {
  const resultsRaw = resultsBranch.readTextFile('results.json');
  const gaps = [
    resultsRaw
      ? `results.json sur ${resultsRef} ne respecte pas le schéma attendu`
      : `results.json absent de la branche ${resultsRef} (et aucun fichier hérité results/reviews/*.json exploitable)`,
  ];
  let gapDetail = '';
  if (!opts.dryRun) {
    const r = await openGapConversation(date, gaps, 'approval');
    gapDetail = r.detail;
  }
  process.stdout.write(
    ['VERDICT: IMPORT_GAP', `Cible : ${target}`, ...gaps.map((g) => `- ${g}`), opts.dryRun ? '--dry-run : conversation d’écart NON ouverte.' : gapDetail].join(
      '\n',
    ) + '\n',
  );
  return;
}
const results: ImportResults = resolved.results;

// Completeness vs the manifest (best-effort — the manifest itself may be
// unfetchable, e.g. this machine never ran a real export for `date`).
const cargoBranch = await fetchBranchContent(target, cargoRef, scratch);
let manifest: ExportManifest | undefined;
// Amorcé par les notes de l'adaptateur hérité : une conversion réussie
// reste un ÉCART à signaler (le producteur cloud doit être corrigé), pas
// un import silencieusement normal.
const gaps: string[] = [...resolved.legacyNotes];
if (cargoBranch) {
  const manifestRaw = cargoBranch.readTextFile('manifest.json');
  const parsed = manifestRaw ? ExportManifestSchema.safeParse(safeJsonParse(manifestRaw)) : undefined;
  if (parsed?.success) manifest = parsed.data;
  else gaps.push(`manifest.json sur ${cargoRef} illisible/invalide — complétude non vérifiable`);
} else {
  gaps.push(`branche ${cargoRef} introuvable — complétude non vérifiable`);
}
if (manifest) {
  const exportedIds = new Set(manifest.items.filter((i) => i.disposition === 'export').map((i) => i.id));
  const resultIds = new Set(results.results.map((r) => r.jobId ?? r.sessionId).filter((v): v is string => Boolean(v)));
  for (const id of exportedIds) {
    if (!resultIds.has(id)) gaps.push(`item exporté "${id}" sans résultat cloud correspondant`);
  }
}

// Per-item transactional ingestion.
const outcomes: string[] = [];
for (let i = 0; i < results.results.length; i++) {
  const r = results.results[i];
  const itemKey = r.jobId ?? r.sessionId ?? `${r.kind}-${i}`;
  const markerP = importMarkerPath(resultsBranch.sha, itemKey);

  if (await fileExists(markerP)) {
    outcomes.push(`${itemKey} : déjà importé (marqueur ${path.basename(markerP)} présent) — sauté`);
    continue;
  }

  if (r.kind === 'improvementDiff') {
    // FAIL-CLOSED sur `skill` absent. `skill` est `optional()` côté zod et
    // le `refine` autorise explicitement un `improvementDiff` sans
    // `jobId`/`sessionId` : la garde précédente (`&& r.skill`) laissait
    // donc un item `{kind:'improvementDiff', changedPaths:[…]}` SAUTER
    // entièrement le scope-lint, alors que le prompt de la routine promet
    // qu'« un scope-lint côté import rejette tout diff plus large ». Le
    // dégât restait borné (aucune application automatique, l'item finit en
    // chip), mais un contrôle qu'on annonce et qui ne s'exécute pas est
    // pire qu'un contrôle absent. Sans `skill`, le scope est indéfinissable
    // — donc rien à autoriser.
    const violation = r.skill
      ? scopeLintViolation(r.skill, r.changedPaths ?? [])
      : 'skill absent — scope indéfinissable, aucun chemin ne peut être autorisé';
    if (violation) {
      outcomes.push(`${itemKey} : REJETÉ — diff hors scope (${violation})`);
      // Le rejet est SCELLÉ par un marqueur (il ne sera jamais rejoué) :
      // il doit donc remonter dans `gaps` — donc au hub — au même titre
      // qu'un side-effect en échec juste en dessous. Sans ça, un diff
      // d'amélioration refusé n'existait que dans le stdout d'UNE
      // invocation de CLI, et disparaissait avec elle.
      gaps.push(`${itemKey} : diff d'amélioration REJETÉ par le scope-lint (${violation}) — scellé, jamais rejoué`);
      if (!opts.dryRun) await writeMarker(markerP, resultsBranch.sha, itemKey, 'rejected-scope-lint');
      continue;
    }
  }

  if (opts.dryRun) {
    outcomes.push(
      `${itemKey} : [dry-run] appliquerait ${r.kind} (marqueur ${path.basename(markerP)} serait posé avant le side-effect)`,
    );
    continue;
  }

  await writeMarker(markerP, resultsBranch.sha, itemKey, 'applying');
  try {
    await applyResultSideEffects(r, { nightDate: date, siblingResults: results.results });
    outcomes.push(`${itemKey} : ingéré (${r.kind})`);
  } catch (err) {
    const detail = (err as Error).message;
    // Fix (round — "un item scellé pour toujours par une panne
    // transitoire") : avant ce fix, `'applying'` posé juste au-dessus
    // n'était JAMAIS corrigé sur cette branche d'échec — un item dont le
    // SEUL problème était recouvrable (ex. variable d'environnement
    // manquante) restait scellé pour toujours, alors que le texte
    // affirmait faussement que le retry le sauterait "par idempotence
    // assumée". Pour les `kind` prouvés sûrs à rejouer (voir

