3805:        const itemResult = ImportResultItemSchema.safeParse(parsed.item);
3889: * données (voir la correction de provenance sur `ImportResultItemSchema` /
4415:    // `verdict-obtained` dont l'`item` ne respecte pas `ImportResultItemSchema`

  /** jobId for a skillJob item, sessionId for a session item. */
  id: z.string().min(1),
  skill: z.string().optional(),
  sessionId: z.string().min(1),
  projectSlug: z.string().optional(),
  headSha: z.string().optional(),
  disposition: ManifestItemDispositionSchema,
  transcriptBytes: z.number().int().nonnegative().optional(),
  transcriptRelPath: z.string().optional(),
  contentSha256: z.string().optional(),
  ageDays: z.number().nonnegative().optional(),
  reason: z.string().min(1),
});
type ManifestItem = z.infer<typeof ManifestItemSchema>;

const SkillDriftEntrySchema = z.object({
  skill: z.string().min(1),
  status: z.enum(['match', 'drift', 'unknown']),
  localSha: z.string().optional(),
  cargoSha: z.string().optional(),
  note: z.string().optional(),
});
type SkillDriftEntry = z.infer<typeof SkillDriftEntrySchema>;

const ExportManifestSchema = z.object({
  schemaVersion: z.literal(1),
  generatedAt: z.string().datetime(),
  cargoBranch: z.string().min(1),
  resultsBranch: z.string().min(1),
  items: z.array(ManifestItemSchema),
  budgets: z.object({
    maxTranscriptBytes: z.number().int().positive(),
    maxCargoBytes: z.number().int().positive(),
    cargoBytesUsed: z.number().int().nonnegative(),
  }),
  skillDrift: z.array(SkillDriftEntrySchema),
  counts: z.record(z.string(), z.number().int().nonnegative()),
});
type ExportManifest = z.infer<typeof ExportManifestSchema>;

const ImportResultKindSchema = z.enum(['skillJobGrade', 'sessionReview', 'improvementDiff', 'note']);

const ImportResultItemSchema = z
  .object({
    kind: ImportResultKindSchema,
    jobId: z.string().min(1).optional(),
    sessionId: z.string().min(1).optional(),
    skill: z.string().min(1).optional(),
    grade: z.number().min(0).max(10).optional(),
    verdict: ReviewVerdictSchema.optional(),
    findings: z.array(SkillJobFindingSchema).optional(),
    sessionState: SessionReviewStateSchema.optional(),
    /**
     * The changed-file paths of an `improvementDiff` result, used by
     * scope-lint. The cloud-side result embeds this list directly rather
     * than a raw unified diff blob — parsing an arbitrary unified diff is
     * out of scope for this lot's deterministic validator (see dispatch:
     * "implémente une vérification simple des chemins listés dans le
     * diff"); a future lot can add real diff parsing if the cloud starts
     * emitting raw patches instead of a file list.
     */
    changedPaths: z.array(z.string()).optional(),
    note: z.string().optional(),
    /**
     * Provenance (chantier "Juge local", Lot 3) — OPTIONNELS pour ne rien
     * casser côté cloud : un `results.json` déjà émis avant ce chantier n'a
     * ni l'un ni l'autre, et `applyResultSideEffects` retombe alors sur les
     * mêmes valeurs qu'avant ('cloud-reviewer' / 'v1'), voir plus bas. Le
     * juge LOCAL, lui, les renseigne toujours (`graderSessionId:
     * 'local-judge'`, `rubricVersion` = celui validé par zod dans
     * `LocalJudgeVerdictSchema`) — sans ces deux champs, une note posée par
     * le juge local se confondrait avec une note du cloud dans les données
     * du banc d'essai lui-même.
     */
    graderSessionId: z.string().min(1).optional(),
    rubricVersion: z.string().min(1).optional(),
  })
  .refine((r) => Boolean(r.jobId || r.sessionId || r.kind === 'note' || r.kind === 'improvementDiff'), {
    message: 'jobId ou sessionId requis (sauf kind="note"/"improvementDiff", identifiés par skill)',
  })
  // Revue adversariale (Lot 8) : `docs/evals/results-contract.md` §3.3 affirme
  // « seul `reviewed` est un verdict légal en sortie de review » mais rien ne
  // l'appliquait — un résultat `sessionReview` pouvait porter n'importe quel
  // état légal du graphe (ex. `skipped_stale`, légal depuis Lot 4) et
  // `applyResultSideEffects` l'aurait appliqué tel quel, alors que ces états
  // sont des dispositions de TRIAGE local, jamais un verdict de review.
  // Applique la même règle AU NIVEAU DU SCHÉMA plutôt qu'en simple convention
  // documentée.
  .refine((r) => r.kind !== 'sessionReview' || r.sessionState === undefined || r.sessionState === 'reviewed', {
    message:
      'sessionReview : sessionState ne peut être que "reviewed" (ou absent) — les autres états sont des dispositions de triage nocturne local, jamais un verdict de review (docs/evals/results-contract.md §3.3)',
  });
type ImportResultItem = z.infer<typeof ImportResultItemSchema>;

const ImportResultsSchema = z.object({
  schemaVersion: z.literal(1),

async function applyResultSideEffects(r: ImportResultItem, ctx?: ApplyResultSideEffectsCtx): Promise<void> {
  if (r.kind === 'skillJobGrade' && r.jobId) {
    const job = await getSkillJob(r.jobId);
    if (!job) throw new Error(`SkillJob ${r.jobId} introuvable localement`);
    await updateSkillJob(
      r.jobId,
      {
        state: 'graded',
        review: {
          grade: r.grade ?? 0,
          gradedAt: new Date().toISOString(),
          // Provenance (Lot 3) : `r.graderSessionId`/`r.rubricVersion` ne
          // sont posés que par le juge LOCAL — un `results.json` cloud
          // antérieur à ce chantier n'a ni l'un ni l'autre, d'où ces mêmes
          // replis qu'avant ('cloud-reviewer' / 'v1') pour ne rien changer
          // au comportement du cloud.
          graderSessionId: r.graderSessionId ?? 'cloud-reviewer',
          rubricVersion: r.rubricVersion ?? 'v1',
          findings: r.findings ?? [],
          verdict: r.verdict ?? (( r.grade ?? 0) < 8 ? 'improvement_candidate' : 'ok'),
        },
      },
      job.updatedAt,
    );
    return;
  }

  if (r.kind === 'sessionReview' && r.sessionId) {
    const stamp = await getSessionStamp(r.sessionId);
    if (!stamp) throw new Error(`SessionReviewStamp ${r.sessionId} introuvable localement`);

    const stateChanges = Boolean(r.sessionState && stamp.state !== r.sessionState);
    // Fix (round-2, revue adversariale — "le rail session jette le verdict
    // payé") : avant cette correction, SEUL un changement d'état déclenchait
    // une écriture — `findings`/`graderSessionId`/`rubricVersion`/`verdict`
    // n'étaient jamais persistés du tout, même quand `state` changeait
    // vraiment (ils étaient simplement absents du patch). `hasReviewDetail`
    // élargit le déclencheur d'écriture à "il y a un détail de revue à
    // persister", même sur un résultat qui ne change PAS `state` (ex. un
    // second passage cloud qui enrichit une session déjà `reviewed`).
    const hasReviewDetail =
      r.grade !== undefined ||
      r.verdict !== undefined ||
      (r.findings && r.findings.length > 0) ||
      Boolean(r.graderSessionId) ||
      Boolean(r.rubricVersion);

    if (stateChanges || hasReviewDetail) {
      await updateSessionStamp(
        r.sessionId,
        {
          ...(stateChanges ? { state: r.sessionState! } : {}),
          ...(r.grade !== undefined ? { score: r.grade } : {}),
          ...(hasReviewDetail
            ? {
                reviewedAt: new Date().toISOString(),
                // Mêmes replis par défaut que la branche `skillJobGrade`
                // ci-dessus — un `results.json` cloud antérieur à ce chantier
                // n'a ni l'un ni l'autre.
                reviewerSessionId: r.graderSessionId ?? 'cloud-reviewer',
                review: {
                  grade: r.grade ?? 0,
                  gradedAt: new Date().toISOString(),
                  graderSessionId: r.graderSessionId ?? 'cloud-reviewer',
                  rubricVersion: r.rubricVersion ?? 'v1',
                  findings: r.findings ?? [],
                  verdict: r.verdict ?? ((r.grade ?? 0) < 8 ? 'improvement_candidate' : 'ok'),
                },
              }
            : {}),
        },
        stamp.updatedAt,
      );
    }
    return;
  }

  if (r.kind === 'improvementDiff') {
    // Titre/label calculé AVANT le `try` : réutilisé tel quel par le repli en
    // chip si `r.skill` lui-même est absent (défensif — le scope-lint de
    // `cmdImport`, exécuté AVANT tout appel à cette fonction, rejette déjà
    // tout `improvementDiff` sans `skill`, donc cette branche ne devrait
    // jamais être atteinte sans `skill` en production ; gardé quand même
    // fail-closed plutôt qu'un throw non catché).
    const skillLabel = r.skill ?? '(skill inconnu)';
    // Suivi de ce que CETTE tentative a réellement mutée hors du store local
    // (revue adversariale rounds 1-2, findings state-safety) — pour que le
    // repli en chip puisse le signaler plutôt que de laisser une trace
    // orpheline muette : `transportedBranch` n'est posé qu'APRÈS un push réel
    // vers le dépôt de skills réel ; `writtenArtifacts` est posé AVANT le
    // premier `atomicWrite` (chemins purs, aucune I/O) pour que le nettoyage
    // best-effort couvre aussi une écriture PARTIELLE (diffPath écrit,
    // backupPath en échec) — `rm(..., {force:true})` ne lève jamais sur un
    // fichier qui n'a en fait jamais été créé.
    let transportedBranch: string | undefined;
    let writtenArtifacts: { diffPath: string; backupPath: string } | undefined;
    try {
      const skill = r.skill;
      if (!skill) {
        throw new Error(
          'skill absent — ne devrait jamais atteindre applyResultSideEffects (le scope-lint de cmdImport ' +
            'rejette déjà tout improvementDiff sans skill avant cet appel)',
        );
      }

      // Pré-vérification du garde mono-proposal AVANT toute mutation réelle
      // (push git, écriture de fichier, ou la gate elle-même) — revue
      // adversariale round 1 (state-safety, P1) : `createGatedProposal`
      // (apply.ts) écrit la conversation `approval` (un vrai `saveConversation`
      // dans le projet hub visible par l'utilisateur) AVANT d'appeler
      // `createImprovementProposal`, qui est le seul endroit qui peut lever
      // `DuplicateProposedProposalError`. Sans ce pré-check, une nuit qui
      // retrouve un skill dont la proposal de la nuit précédente est encore
      // `proposed` (cas ORDINAIRE, pas un cas limite — cadence nocturne vs
      // relecture humaine asynchrone) pousse quand même une branche réelle sur
      // le dépôt de skills ET écrit une gate `approval` réelle dans le hub,
      // puis échoue APRÈS coup : la gate reste orpheline pour toujours (aucune
      // ImprovementProposal ne référence jamais un `gateRef` qui n'a pas été
      // créé), et le commentaire qui suivait ici affirmait à tort que "cette
      // voie ne touche jamais une gate" — faux dans ce cas précis. Ce
      // pré-check suit le même idiome que `superviseChangesRequested`
      // (apply.ts, § ORDERING) : résoudre/transitionner la ligne 'proposed'
