describe('reviews/apply.ts', () => {
  test('chemin A — cycle complet proposed -> applied -> reverted (skill générique)', async () => {
    await freshRoot();
    const fxRoot = await freshFixtureDir();
    const skill = 'my-fake-skill';

    const bareRepo = path.join(fxRoot, 'remote.git');
    await initBareRepo(bareRepo);
    const beforeSha = await initMainBranch(bareRepo, {
      [`${skill}/SKILL.md`]: '# my-fake-skill\n\nv1 content.\n',
    });

    const { proposal, branch, gateRef } = await applyMod.createGatedProposal(
      baseGateInput({ skill, beforeSha }),
    );
    expect(branch.startsWith(`improve/${skill}-`)).toBe(true);

    await pushBranchFrom(bareRepo, branch, beforeSha, {
      [`${skill}/SKILL.md`]: '# my-fake-skill\n\nv2 content (improved).\n',
    });

    await answerGate(gateRef, 'approved');

    const installRoot = path.join(fxRoot, 'install-root');
    const ctx: ApplyContext = {
      skillRepo: {
        remote: bareRepo,
        integrationClone: path.join(fxRoot, 'integration-clone'),
        installRoot,
      },
    };

    const outcome = await applyMod.applyProposal(proposal.id, ctx);
    expect(outcome.kind).toBe('applied');
    if (outcome.kind !== 'applied') throw new Error('unreachable');
    expect(outcome.proposal.state).toBe('applied');
    expect(outcome.proposal.mergeSha).toBeTruthy();
    expect(outcome.proposal.appliedAt).toBeTruthy();

    const installedContent = await readFile(path.join(installRoot, skill, 'SKILL.md'), 'utf8');
    expect(installedContent).toContain('v2 content');

    const markerRaw = await readFile(path.join(installRoot, skill, '.ws-install-sha.json'), 'utf8');
    expect(JSON.parse(markerRaw).sha).toBe(outcome.proposal.mergeSha);

    expect(remoteBranchExists(bareRepo, branch)).toBe(false);
    const mergeSha = outcome.proposal.mergeSha;
    if (!mergeSha) throw new Error('mergeSha manquant');
    expect(gitOut(['rev-parse', 'main'], bareRepo)).toBe(mergeSha);

    // --- revert ---
    const revertOutcome = await applyMod.revertProposal(proposal.id, ctx);
    expect(revertOutcome.kind).toBe('reverted');
    if (revertOutcome.kind !== 'reverted') throw new Error('unreachable');
    expect(revertOutcome.proposal.state).toBe('reverted');

    const revertedContent = await readFile(path.join(installRoot, skill, 'SKILL.md'), 'utf8');
    expect(revertedContent).toContain('v1 content');
    expect(revertedContent).not.toContain('v2 content');

    const markerAfterRevert = JSON.parse(
      await readFile(path.join(installRoot, skill, '.ws-install-sha.json'), 'utf8'),
    );
    expect(markerAfterRevert.sha).not.toBe(outcome.proposal.mergeSha);
  });

